<?php
namespace Tests\Feature;
use App\Domain\AI\Agents\Enums\{AgentStatus,AgentType,AgentVersionStatus};use App\Domain\AI\Agents\Models\{Agent,AgentVersion};use App\Domain\AI\Knowledge\Chunking\DeterministicKnowledgeChunker;use App\Domain\AI\Knowledge\Data\{KnowledgeContentData,KnowledgeSearchQuery};use App\Domain\AI\Knowledge\Enums\{KnowledgeIndexStatus,KnowledgeSourceStatus};use App\Domain\AI\Knowledge\Jobs\BuildKnowledgeIndexJob;use App\Domain\AI\Knowledge\Models\{AgentVersionKnowledgeSource,KnowledgeChunk,KnowledgeIndex,KnowledgeSource};use App\Domain\AI\Knowledge\Retrieval\LexicalKnowledgeRetriever;use App\Domain\AI\Knowledge\Services\{ApproveKnowledgeVersionService,AttachKnowledgeToAgentVersionService,BuildKnowledgeIndexService,CreateKnowledgeRevisionService,CreateKnowledgeSourceService,RequestKnowledgeIndexingService};use App\Domain\AI\Jobs\AiTenantJobExecution;use App\Domain\AI\Support\Exceptions\AiImmutableAttributeException;use App\Domain\Network\Billing\Models\{Entitlement,Subscription};use App\Domain\Network\Catalog\Models\{Module,Plan};use App\Domain\Network\Tenancy\Models\{Tenant,TenantDomain,TenantMembership};use App\Domain\Network\Tenancy\TenantContext;use App\Models\User;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\{Bus,DB,Schema};use Tests\TestCase;
final class AiKnowledgeRetrievalTest extends TestCase
{
 protected function setUp():void{parent::setUp();config(['database.default'=>'sqlite','database.connections.sqlite.database'=>':memory:','ai.enabled'=>true,'ai.entitlement.module_code'=>'AI_CORE','queue.default'=>'sync']);$this->schema();app(TenantContext::class)->clear();}
 public function test_chunker_is_deterministic_unicode_safe_and_faq_located():void{$chunker=app(DeterministicKnowledgeChunker::class);$manual=KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>str_repeat('Información útil áéíóú. ',90)]);$one=$chunker->chunks($manual);$two=$chunker->chunks($manual);$this->assertEquals($one,$two);$this->assertGreaterThan(1,count($one));foreach($one as$chunk){$this->assertLessThanOrEqual(1200,$chunk->characterCount);$this->assertSame(mb_strlen($chunk->content),$chunk->characterCount);}$faq=$chunker->chunks(KnowledgeContentData::fromArray(['type'=>'faq','entries'=>[['question'=>'¿Cuál es el horario?','answer'=>'Abrimos de nueve a seis.']]]));$this->assertStringContainsString('Pregunta: ¿Cuál es el horario?',$faq[0]->content);$this->assertSame(1,$faq[0]->locator['faq_number']);}
 public function test_request_is_canonical_idempotent_and_dispatches_tenant_job():void{[$t,$u]=$this->authorized('request');$source=$this->approved($u,'Manual','Dato indexable');Bus::fake();$one=app(RequestKnowledgeIndexingService::class)->request($u,$source,$source->versions->first());$two=app(RequestKnowledgeIndexingService::class)->request($u,$source,$source->versions->first());$this->assertTrue($one->is($two));$this->assertSame(1,KnowledgeIndex::count());Bus::assertDispatched(BuildKnowledgeIndexJob::class,fn($job)=>$job->tenantId()===$t->id);$copy=unserialize(serialize(new BuildKnowledgeIndexJob($t->id,$one->id)));$this->assertSame($t->id,$copy->tenantId());}
 public function test_build_persists_ready_chunks_and_ready_reexecution_is_idempotent():void{[$t,$u]=$this->authorized('build');$source=$this->approved($u,'Manual','Horario de atención de lunes a viernes.');Bus::fake();$index=app(RequestKnowledgeIndexingService::class)->request($u,$source,$source->versions->first());$ready=app(BuildKnowledgeIndexService::class)->build($index->id);$this->assertSame(KnowledgeIndexStatus::Ready,$ready->status);$this->assertSame($ready->chunk_count,KnowledgeChunk::count());$before=KnowledgeChunk::pluck('content_checksum')->all();app(BuildKnowledgeIndexService::class)->build($index->id);$this->assertSame($before,KnowledgeChunk::pluck('content_checksum')->all());}
 public function test_job_restores_and_clears_tenant_context_on_success_and_exception():void{[$t,$u]=$this->authorized('job');$source=$this->approved($u,'Manual','Contenido');Bus::fake();$index=app(RequestKnowledgeIndexingService::class)->request($u,$source,$source->versions->first());app(TenantContext::class)->clear();$job=new BuildKnowledgeIndexJob($t->id,$index->id);$job->handle(app(AiTenantJobExecution::class),app());$this->assertFalse(app(TenantContext::class)->hasTenant());app(TenantContext::class)->set($t);$second=$this->approved($u,'Fallo','Contenido dos');$bad=app(RequestKnowledgeIndexingService::class)->request($u,$second,$second->versions->first());KnowledgeChunk::creating(fn()=>throw new \RuntimeException('controlled'));app(TenantContext::class)->clear();try{(new BuildKnowledgeIndexJob($t->id,$bad->id))->handle(app(AiTenantJobExecution::class),app());$this->fail('Job failure expected.');}catch(\RuntimeException){$this->assertFalse(app(TenantContext::class)->hasTenant());}app(TenantContext::class)->set($t);$this->assertSame(KnowledgeIndexStatus::Failed,$bad->fresh()->status);$this->assertSame(0,KnowledgeChunk::where('knowledge_index_id',$bad->id)->count());}
 public function test_failed_retry_and_archived_or_draft_sources_fail_closed():void{[$t,$u]=$this->authorized('states');$source=$this->approved($u,'Retry','Contenido');Bus::fake();$index=app(RequestKnowledgeIndexingService::class)->request($u,$source,$source->versions->first());DB::table('ai_knowledge_indexes')->where('id',$index->id)->update(['status'=>'failed','safe_error_code'=>'indexing_failed']);$this->assertSame(KnowledgeIndexStatus::Ready,app(BuildKnowledgeIndexService::class)->build($index->id)->status);$draft=app(CreateKnowledgeSourceService::class)->create($u,'Draft',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato']));$this->expectException(\DomainException::class);app(RequestKnowledgeIndexingService::class)->request($u,$draft,$draft->versions->first());}
 public function test_archived_source_is_excluded_from_request_build_and_retrieval():void{[$t,$u]=$this->authorized('archived');$source=$this->approved($u,'Archivo','Clave retirada');[$agent,$av]=$this->agent($u);$version=$source->versions->first();app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$version);Bus::fake();$index=app(RequestKnowledgeIndexingService::class)->request($u,$source,$version);app(BuildKnowledgeIndexService::class)->build($index->id);DB::transaction(function()use($u,$source){$a=app(\App\Domain\AI\Agents\Services\AiLifecycleAuthorization::class)->authorize($u);KnowledgeSource::findOrFail($source->id)->archive($a);});$this->assertSame([],app(LexicalKnowledgeRetriever::class)->retrieve($av,KnowledgeSearchQuery::from('clave retirada')));try{app(RequestKnowledgeIndexingService::class)->request($u,$source,$version);$this->fail('Archived request expected.');}catch(\App\Domain\AI\Knowledge\Exceptions\ArchivedKnowledgeSourceException){$this->assertSame(KnowledgeIndexStatus::Ready,$index->fresh()->status);}}
 public function test_retrieval_is_limited_to_linked_ready_version_and_ordered():void{[$t,$u]=$this->authorized('retrieve');$linked=$this->approved($u,'Horarios','Atención lunes a viernes nueve a seis.');$unlinked=$this->approved($u,'Privada','Atención secreta domingo.');[$agent,$av]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$linked->versions->first());Bus::fake();foreach([$linked,$unlinked]as$source){$idx=app(RequestKnowledgeIndexingService::class)->request($u,$source,$source->versions->first());app(BuildKnowledgeIndexService::class)->build($idx->id);}$matches=app(LexicalKnowledgeRetriever::class)->retrieve($av,KnowledgeSearchQuery::from('atención lunes'));$this->assertNotEmpty($matches);$this->assertSame('Horarios',$matches[0]->sourceName);$this->assertNotContains('Privada',array_column($matches,'sourceName'));$this->assertSame([],app(LexicalKnowledgeRetriever::class)->retrieve($av,KnowledgeSearchQuery::from('palabra inexistente')));$this->assertObjectNotHasProperty('tenantId',$matches[0]);$this->assertObjectNotHasProperty('checksum',$matches[0]);}
 public function test_replacement_changes_draft_retrieval_and_historical_agent_keeps_v1():void{[$t,$u]=$this->authorized('history');$source=$this->approved($u,'Política','Entrega anterior azul');$v1=$source->versions->first();[$a1,$av1]=$this->agent($u);[$a2,$av2]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$a1,$v1);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$a2,$v1);Bus::fake();$i1=app(RequestKnowledgeIndexingService::class)->request($u,$source,$v1);app(BuildKnowledgeIndexService::class)->build($i1->id);$v2=app(ApproveKnowledgeVersionService::class)->approve($u,app(CreateKnowledgeRevisionService::class)->create($u,$source,KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Entrega nueva verde'])));$i2=app(RequestKnowledgeIndexingService::class)->request($u,$source,$v2);app(BuildKnowledgeIndexService::class)->build($i2->id);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$a1,$v2);$this->assertSame('Entrega nueva verde',app(LexicalKnowledgeRetriever::class)->retrieve($av1,KnowledgeSearchQuery::from('nueva verde'))[0]->excerpt);$this->assertSame('Entrega anterior azul',app(LexicalKnowledgeRetriever::class)->retrieve($av2,KnowledgeSearchQuery::from('anterior azul'))[0]->excerpt);}
 public function test_cross_tenant_and_generic_writes_fail_closed():void{[$a,$ua]=$this->authorized('ta');$source=$this->approved($ua,'A','Dato A');Bus::fake();$index=app(RequestKnowledgeIndexingService::class)->request($ua,$source,$source->versions->first());app(BuildKnowledgeIndexService::class)->build($index->id);$chunk=KnowledgeChunk::firstOrFail();[$b,$ub]=$this->authorized('tb');$this->assertNull(KnowledgeIndex::find($index->id));app(TenantContext::class)->set($a);foreach([[KnowledgeIndex::class,$index->id],[KnowledgeChunk::class,$chunk->id]]as[$class,$id]){foreach([fn()=>tap($class::findOrFail($id),fn($m)=>$m->tenant_id=$b->id)->save(),fn()=>tap($class::findOrFail($id),fn($m)=>$m->tenant_id=$b->id)->saveQuietly(),fn()=>$class::query()->whereKey($id)->update(['tenant_id'=>$b->id]),fn()=>$class::query()->increment('id'),fn()=>$class::query()->decrement('id'),fn()=>$class::query()->insert([['tenant_id'=>$a->id]]),fn()=>$class::query()->insertOrIgnore([['tenant_id'=>$a->id]]),fn()=>$class::query()->insertGetId(['tenant_id'=>$a->id]),fn()=>$class::query()->upsert([['tenant_id'=>$a->id]],['tenant_id']),fn()=>$class::findOrFail($id)->delete(),fn()=>$class::findOrFail($id)->deleteQuietly(),fn()=>$class::query()->whereKey($id)->delete(),fn()=>$class::destroy($id),fn()=>$class::query()->forceDelete(),fn()=>$class::query()->truncate()]as$write){try{$write();$this->fail('Generic write must fail.');}catch(AiImmutableAttributeException){$this->addToAssertionCount(1);}}$this->assertDatabaseHas((new$class)->getTable(),['id'=>$id,'tenant_id'=>$a->id]);}}
 public function test_http_owner_can_prepare_and_search_while_payloads_and_roles_are_rejected():void{[$t,$u]=$this->httpTenant('http-ret','owner');$source=$this->approved($u,'FAQ pública','El horario es de nueve a seis.');$version=$source->versions->first();[$agent]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$version);Bus::fake();$base='http://http-ret.test';$this->actingAs($u)->post($base.'/admin/ai-knowledge/'.$source->uuid.'/versions/'.$version->uuid.'/index',['_token'=>'framework'])->assertRedirect();$index=KnowledgeIndex::firstOrFail();app(BuildKnowledgeIndexService::class)->build($index->id);$this->post($base.'/admin/ai-agents/'.$agent->id.'/knowledge/search',['question'=>'¿Cuál es el horario?','_token'=>'framework'])->assertOk()->assertSee('Probar búsqueda de conocimiento')->assertSee('FAQ pública')->assertSee('Todavía no genera una respuesta conversacional');$this->post($base.'/admin/ai-agents/'.$agent->id.'/knowledge/search',['question'=>'<script>x</script>'])->assertSessionHasErrors('question');$this->post($base.'/admin/ai-agents/'.$agent->id.'/knowledge/search',['question'=>'horario','tenant_id'=>9])->assertSessionHasErrors('tenant_id');$this->post($base.'/admin/ai-knowledge/'.$source->uuid.'/versions/'.$version->uuid.'/index',['_method'=>'PUT'])->assertStatus(405);foreach(['viewer','operator','staff','support','billing']as$role){$blocked=$this->user($role.'@ret.test');$this->membership($t,$blocked,$role);$this->actingAs($blocked)->post($base.'/admin/ai-agents/'.$agent->id.'/knowledge/search',['question'=>'horario'])->assertForbidden();}$admin=$this->user('admin@ret.test');$this->membership($t,$admin,'admin');$this->actingAs($admin)->post($base.'/admin/ai-agents/'.$agent->id.'/knowledge/search',['question'=>'horario'])->assertOk();$this->assertSame(1,KnowledgeIndex::count());}
 public function test_indexing_migration_up_down_up_keeps_foreign_keys():void{$m=$this->indexingMigration();$this->assertSame(1,(int)DB::selectOne('PRAGMA foreign_keys')->foreign_keys);$this->assertNotEmpty(DB::select("PRAGMA foreign_key_list('ai_knowledge_chunks')"));$indexes=collect(DB::select("PRAGMA index_list('ai_knowledge_indexes')"))->pluck('name');$this->assertContains('ai_knowledge_indexes_version_uq',$indexes);$m->down();$this->assertSame(1,(int)DB::selectOne('PRAGMA foreign_keys')->foreign_keys);$m->up();$this->assertTrue(Schema::hasTable('ai_knowledge_chunks'));}
 private function approved(User$u,string$name,string$body):KnowledgeSource{$source=app(CreateKnowledgeSourceService::class)->create($u,$name,KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>$body]));app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());return$source->fresh('versions');}
 private function authorized(string$s):array{$t=Tenant::create(['name'=>$s,'slug'=>$s,'status'=>'active']);$u=$this->user($s.'@test');$this->membership($t,$u,'owner');$m=Module::firstOrCreate(['code'=>'AI_CORE'],['name'=>'AI Core','type'=>'core','is_active'=>true,'sort_order'=>1]);$p=Plan::create(['code'=>'P'.$t->id,'name'=>'AI','status'=>'active','currency'=>'MXN']);$sub=Subscription::create(['tenant_id'=>$t->id,'plan_id'=>$p->id,'status'=>'active','started_at'=>now()->subDay(),'current_period_start'=>now()->subDay(),'current_period_end'=>now()->addMonth()]);Entitlement::create(['subscription_id'=>$sub->id,'tenant_id'=>$t->id,'module_id'=>$m->id,'code'=>'AI_CORE','is_enabled'=>true,'source'=>'plan']);app(TenantContext::class)->set($t);return[$t,$u];}
 private function httpTenant(string$s,string$role):array{[$t,$u]=$this->authorized($s);$t->memberships()->where('user_id',$u->id)->update(['role'=>$role]);TenantDomain::create(['tenant_id'=>$t->id,'domain'=>$s.'.test','type'=>'subdomain','environment'=>'sandbox','is_primary'=>true,'status'=>'verified','verified_at'=>now()]);return[$t,$u];}
 private function user(string$email):User{return User::create(['name'=>'User','email'=>$email,'password'=>'hashed','empresa_id'=>1]);}private function membership(Tenant$t,User$u,string$role):TenantMembership{return TenantMembership::create(['tenant_id'=>$t->id,'user_id'=>$u->id,'role'=>$role,'status'=>'active']);}
 private function agent(User$u):array{$a=new Agent();$a->code='R'.uniqid();$a->name='Agente';$a->type=AgentType::Sales;$a->status=AgentStatus::Draft;$a->created_by_user_id=$u->id;$a->save();$v=new AgentVersion();$v->agent_id=$a->id;$v->version_number=1;$v->status=AgentVersionStatus::Draft;$v->schema_version='1.0';$v->configuration=['capabilities'=>[],'guardrails'=>[],'handoff'=>[],'outcomes'=>[],'capacity'=>[],'sla'=>[],'privacy'=>[],'channels'=>[]];$v->created_by_user_id=$u->id;$v->save();return[$a,$v];}
 private function schema():void{DB::statement('PRAGMA foreign_keys=ON');Schema::create('users',function(Blueprint$t){$t->id();$t->string('name');$t->string('email')->unique();$t->string('password');$t->unsignedBigInteger('empresa_id');$t->rememberToken();$t->timestamps();});Schema::create('network_tenants',function(Blueprint$t){$t->id();$t->uuid('uuid')->unique();$t->string('name');$t->string('slug')->unique();$t->string('status');$t->timestamps();});Schema::create('network_tenant_domains',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->string('domain')->unique();$t->string('type');$t->string('environment');$t->boolean('is_primary');$t->string('status');$t->timestamp('verified_at')->nullable();$t->timestamps();});Schema::create('network_tenant_brandings',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id')->unique();$t->string('brand_name')->nullable();$t->string('logo_path')->nullable();$t->string('favicon_path')->nullable();$t->string('primary_color')->nullable();$t->string('secondary_color')->nullable();$t->string('accent_color')->nullable();$t->timestamps();});Schema::create('network_tenant_memberships',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('user_id');$t->string('role');$t->string('status');$t->timestamps();});Schema::create('network_plans',function(Blueprint$t){$t->id();$t->string('code')->unique();$t->string('name');$t->text('description')->nullable();$t->string('status');$t->char('currency',3);$t->timestamps();});Schema::create('network_modules',function(Blueprint$t){$t->id();$t->string('code')->unique();$t->string('name');$t->string('type');$t->boolean('is_active');$t->unsignedSmallInteger('sort_order');$t->timestamps();});Schema::create('network_subscriptions',function(Blueprint$t){$t->id();$t->uuid('uuid')->unique();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('plan_id');$t->string('status');foreach(['started_at','current_period_start','current_period_end','trial_ends_at','grace_ends_at','canceled_at','ended_at']as$c)$t->timestamp($c)->nullable();$t->timestamps();});Schema::create('network_entitlements',function(Blueprint$t){$t->id();$t->unsignedBigInteger('subscription_id');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('module_id');$t->string('code');$t->boolean('is_enabled');$t->string('source');$t->timestamps();});(require base_path('database/migrations/2026_08_22_100000_create_ai_agent_domain_tables.php'))->up();(require base_path('database/migrations/2026_08_23_100000_add_ai_agent_lifecycle.php'))->up();(require base_path('database/migrations/2026_08_25_100000_create_ai_knowledge_foundation.php'))->up();$this->indexingMigration()->up();}
 private function indexingMigration():object{return require base_path('database/migrations/2026_08_26_100000_create_ai_knowledge_indexing.php');}
}
